#!/usr/bin/env -S bash -euo pipefail

LP="$1"

if [ -z "$LP" ]; then
    echo "Usage: $0 <PATH-TO-LESSPASS-CLI>"
    exit 2
fi

# Выводим заголовок, импорты и тестовый раннер
cat << 'EOF'
//! Tests lesspass.rs using lesspass-cli as oracle.
//!
//! The test vectors in this file are generated by lesspass-cli using
//! the script `make-blackbox-tests.sh` located in the same directory
//! as this test.

use lesspass::{generate_salt, generate_entropy, render_password, Algorithm, CharacterSet};

fn t(
    _test_id: usize,
    site: &str,
    login: &str,
    password: &str,
    counter: u32,
    length: usize,
    expected_passwords: &[&str],
) {
    let salt = generate_salt(site, login, counter);
    let entropy = generate_entropy(password, &salt, Algorithm::SHA256, 100_000);

    let mut expected_idx = 0;

    for lower in [CharacterSet::empty(), CharacterSet::Lowercase] {
        for upper in [CharacterSet::empty(), CharacterSet::Uppercase] {
            for digits in [CharacterSet::empty(), CharacterSet::Digits] {
                for symbols in [CharacterSet::empty(), CharacterSet::Symbols] {
                    let charset = lower | upper | digits | symbols;
                    if charset.is_empty() {
                        continue;
                    }

                    let generated = render_password(&entropy, charset, length);
                    assert_eq!(
                        generated,
                        expected_passwords[expected_idx],
                        "Test case failed for site: {}, login: {}, counter: {}, length: {}",
                        site, login, counter, length
                    );
                    expected_idx += 1;
                }
            }
        }
    }
}

EOF

# Генерация векторов
TEST=0
for SITE in example.org example.net; do
    for LOGIN in user@example.org user; do
        for PASSWORD in password foobar; do
            for COUNTER in 0 1 8 32 100000; do
                for LENGTH in 12 16 32; do
                    echo "#[test]"

                    if [ $TEST -ge 4 ]; then
                        echo "#[cfg_attr(debug_assertions, ignore)]"
                    fi

                    echo "fn vectors_$(printf "%03d" $TEST)() {"
                    echo -n "    t($TEST, "
                    echo -n "\"$SITE\", "
                    echo -n "\"$LOGIN\", "
                    echo -n "\"$PASSWORD\", "
                    echo -n "$COUNTER, "
                    echo -n "$LENGTH, &["
                    for LOWER in no- ""; do
                        for UPPER in no- ""; do
                            for DIGITS in no- ""; do
                                for SYMBOLS in no- ""; do
                                    if [ "$LOWER$UPPER$DIGITS$SYMBOLS" \
                                             = "no-no-no-no-" ]; then
                                        continue
                                    fi

                                    ARG_LOWER=""
                                    ARG_UPPER=""
                                    ARG_DIGITS=""
                                    ARG_SYMBOLS=""

                                    if [ "$LOWER" = "no-" ]; then ARG_LOWER="--no-lower"; fi
                                    if [ "$UPPER" = "no-" ]; then ARG_UPPER="--no-upper"; fi
                                    if [ "$DIGITS" = "no-" ]; then ARG_DIGITS="--no-digits"; fi
                                    if [ "$SYMBOLS" = "no-" ]; then ARG_SYMBOLS="--no-symbols"; fi

                                    echo -n "\"$($LP "$SITE" "$LOGIN" "$PASSWORD" \
                                                       --counter $COUNTER \
                                                       --length $LENGTH \
                                                       $ARG_LOWER \
                                                       $ARG_UPPER \
                                                       $ARG_DIGITS \
                                                       $ARG_SYMBOLS \
                                                   | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' )\""
                                    echo -n ", "
                                done
                            done
                        done
                    done
                    echo "]);"
                    echo "}"
                    echo
                    TEST="$(($TEST + 1))"
                done
            done
        done
    done
done
